properties.query:
let windowSize = 90m;
let ApprovedArm = _GetWatchlist('Approved_Arm_Operator_List') | project OperatorId;
// S34: 정찰/무차별 계정접근
let S34 =
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'login_failure'
    | summarize FailCount=count(), T1=min(TimeGenerated) by Operator, ClientIp
    | where FailCount >= 5;
// S36: 임무 자기승인
let S36 =
    UAVMission_CL
    | where TimeGenerated > ago(windowSize)
    | where Planner == Approver
    | project T2=TimeGenerated, Operator=Planner, MissionId;
// S3: 비인가 무장 (UAVId 제거)
let S3 =
    UAVWeapon_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('arm','fire')
    | where ArmedBy == Operator or Operator !in (ApprovedArm)
    | project T3=TimeGenerated, Operator, WeaponId;
S34
| join kind=inner (S36) on Operator
| where T2 >= T1 and T2 <= T1 + 45m
| join kind=inner (S3) on Operator
| where T3 >= T2 and T3 <= T2 + 30m
| extend CampaignType = "C4_정찰_임무자기승인_무장"
| extend StepSummary = strcat("S34@", tostring(T1), "(실패:", tostring(FailCount), "회)→S36@", tostring(T2), "→S3@", tostring(T3))
| extend Severity = "High"
| project T1, T2, T3, Operator, MissionId, WeaponId, FailCount, CampaignType, StepSummary, Severity
